        ///<summary>
        ///Reserve one random item. Payment must cover the four line items:
        ///  price          - creator (held until reveal)
        ///  revealFee      - whoever calls reveal (keeper bounty)
        ///  commit box MBR - refundable (2500 + 400 * (9-byte key + 72-byte Commit) = 34,900 today)
        ///  deliveryBudget - refundable delivery deposit (direct refund or carried to the ARC-59 inbox)
        ///Anything paid above that is added to the refundable deposit.  is the price the
        ///buyer saw, so a price raised while the commit is in flight makes it fail instead of charging more.
        ///</summary>
        /// <param name="payment"> </param>
        /// <param name="maxPrice"> </param>
        public async Task<ulong> Commit(PaymentTransaction payment, ulong maxPrice, Account _tx_sender, ulong? _tx_fee, string _tx_note = "", ulong _tx_roundValidity = 1000, List<BoxRef>? _tx_boxes = null, List<Transaction>? _tx_transactions = null, List<ulong>? _tx_assets = null, List<ulong>? _tx_apps = null, List<Address>? _tx_accounts = null, AVM.ClientGenerator.Core.OnCompleteType _tx_callType = AVM.ClientGenerator.Core.OnCompleteType.NoOp)
        {
            _tx_boxes ??= new List<BoxRef>();
            _tx_transactions ??= new List<Transaction>();
            _tx_assets ??= new List<ulong>();
            _tx_apps ??= new List<ulong>();
            _tx_accounts ??= new List<Address>();
            _tx_transactions.AddRange(new List<Transaction> { payment });
            byte[] abiHandle = { 231, 46, 46, 79 };
            var maxPriceAbi = new AVM.ClientGenerator.ABI.ARC4.Types.UInt64(); maxPriceAbi.From(maxPrice);

            var result = await base.CallApp(new List<object> { abiHandle, payment, maxPriceAbi }, _tx_fee: _tx_fee, _tx_callType: _tx_callType, _tx_roundValidity: _tx_roundValidity, _tx_note: _tx_note, _tx_sender: _tx_sender, _tx_transactions: _tx_transactions, _tx_apps: _tx_apps, _tx_assets: _tx_assets, _tx_accounts: _tx_accounts, _tx_boxes: _tx_boxes);
            var lastLogBytes = result.Last();
            if (lastLogBytes.Length < 4 || lastLogBytes[0] != 21 || lastLogBytes[1] != 31 || lastLogBytes[2] != 124 || lastLogBytes[3] != 117) throw new Exception("Invalid ABI handle");
            var lastLogReturnData = lastLogBytes.Skip(4).ToArray();
            var returnValueObj = new AVM.ClientGenerator.ABI.ARC4.Types.UInt64();
            returnValueObj.Decode(lastLogReturnData);
            return BitConverter.ToUInt64(ReverseIfLittleEndian(lastLogReturnData), 0);

        }

